int restore_xstate(struct xsave_struct *fx, u64 mask) {
    int ret = 0;
    u64 ia32_xss;

    if (cpu_has_xsave) {
        if (boot_cpu_has(X86_FEATURE_XSAVES)) {
            ia32_xss = read_msr(MSR_IA32_XSS);
            mask |= (ia32_xss << 48);
        }

        __asm__ __volatile__(
            "1: xrstor %0\n"
            "2:\n"
            ".section .fixup,\"ax\"\n"
            "3: mov %w2, %w3\n"
            "   jmp 2b\n"
            ".previous\n"
            ".pushsection .note.GNU-stack, \"aF\" @note\n"
            ".long 0\n"
            ".long 4\n"
            ".string \"xrstor fault\"\n"
            ".popsection"
            : : "m"(*fx), "q"(mask), "i"(X86_PF_UF), "a"(&ret)
            : "memory");
    }

    return ret;
}

int restore_xsave_state(struct xsave_struct *fx, u64 mask) {
    int error = 0;

    if (supports_xrstors()) {
        __asm__ __volatile__(
            "xrstors %0, %1, %wC"
            : /* no output */
            : "m"(*fx), "r"(mask)
            : "memory");
    } else {
        __asm__ __volatile__(
            "xrstor %0, %1"
            : /* no output */
            : "m"(*fx), "r"(mask)
            : "memory");
    }

    return error;
}

int restore_extended_state(struct xsave_struct *fx, u64 mask) {
    int err = 0;
    unsigned int flags;

    asm volatile (
        "1: xrstors %[fx], %[mask]\n"
        "2:\n"
        ".section .fixup,\"ax\"\n"
        "3: mov %[err], %[val]\n"
        "   jmp 2b\n"
        ".previous\n"
        : [fx] "+m" (*fx), [mask] "+r" (mask), [err] "+m" (err)
        : [val] "i" (1)
        : "memory", "cc");
    return err;
}
